steps.solution:
#include <iostream>
using namespace std;

int main() {
    int distance = 120;
    int speed = 40;
    int total_samples = 47;
    int sensors = 4;

    int flight_hours = distance / speed;
    int unassigned = total_samples % sensors;

    cout << "HOURS: " << flight_hours << endl;
    cout << "UNASSIGNED: " << unassigned << endl;
    return 0;
}

